// Separa los archivos del multipart en un item por archivo, valida tipo real
// (firma de bytes) y tamaño, y calcula el SHA-256. No registra contenido.
const crypto = require('crypto');
const MAX_BYTES = 10 * 1024 * 1024;
const HEIC_BRANDS = ['heic', 'heix', 'hevc', 'hevx', 'heim', 'heis', 'mif1', 'msf1'];

function detectarTipo(buf) {
  if (buf.length >= 5 && buf.subarray(0, 1024).indexOf('%PDF-') !== -1) return { mime: 'application/pdf', ext: 'pdf' };
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return { mime: 'image/jpeg', ext: 'jpg' };
  if (buf.length >= 8 && buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return { mime: 'image/png', ext: 'png' };
  if (buf.length >= 12 && buf.subarray(0, 4).toString('latin1') === 'RIFF' && buf.subarray(8, 12).toString('latin1') === 'WEBP') return { mime: 'image/webp', ext: 'webp' };
  if (buf.length >= 12 && buf.subarray(4, 8).toString('latin1') === 'ftyp' && HEIC_BRANDS.includes(buf.subarray(8, 12).toString('latin1'))) return { mime: 'image/heic', ext: 'heic' };
  return null;
}

const entrada = $input.first();
const binarios = entrada.binary || {};
const claves = Object.keys(binarios);
const salida = [];

// Cliente de la gestoría: campo multipart o query «cliente_id» (opcional). Si falta, se
// asigna después por el NIF del destinatario o a «Personal».
const cuerpo = entrada.json && entrada.json.body && typeof entrada.json.body === 'object' ? entrada.json.body : {};
const query = entrada.json && entrada.json.query && typeof entrada.json.query === 'object' ? entrada.json.query : {};
const crudoCliente = cuerpo.cliente_id ?? query.cliente_id;
let cliente_id = null;
if (crudoCliente !== undefined && crudoCliente !== null && String(crudoCliente).trim() !== '') {
  const t = String(Array.isArray(crudoCliente) ? crudoCliente[0] : crudoCliente).trim();
  const existe = /^\d{1,12}$/.test(t) && $('Leer clientes').all().some((i) => i.json && i.json.id === Number(t) && i.json.activo !== false);
  if (!existe) {
    return [{ json: { orden: 0, archivo: null, valido: false, estado: 'rechazado', error: 'El cliente_id indicado no existe o no está activo (GET /clientes).' }, pairedItem: { item: 0 } }];
  }
  cliente_id = Number(t);
}

if (claves.length === 0) {
  return [{ json: { orden: 0, archivo: null, valido: false, estado: 'rechazado', error: 'No se ha recibido ningún archivo. Envía uno o varios en el campo "archivo" (multipart/form-data).' }, pairedItem: { item: 0 } }];
}

for (let i = 0; i < claves.length; i++) {
  const clave = claves[i];
  const meta = binarios[clave];
  const nombre = meta.fileName || clave;
  const base = { orden: i, archivo: nombre, cliente_id };
  let buf;
  try {
    buf = await this.helpers.getBinaryDataBuffer(0, clave);
  } catch (e) {
    salida.push({ json: { ...base, valido: false, estado: 'rechazado', error: 'No se pudo leer el archivo recibido.' }, pairedItem: { item: 0 } });
    continue;
  }
  if (buf.length === 0) {
    salida.push({ json: { ...base, tamano: 0, valido: false, estado: 'rechazado', error: 'El archivo está vacío.' }, pairedItem: { item: 0 } });
    continue;
  }
  if (buf.length > MAX_BYTES) {
    const mb = (buf.length / 1048576).toFixed(1);
    salida.push({ json: { ...base, tamano: buf.length, valido: false, estado: 'rechazado', error: `El archivo ocupa ${mb} MB; el máximo es 10 MB.` }, pairedItem: { item: 0 } });
    continue;
  }
  const tipo = detectarTipo(buf);
  if (!tipo) {
    salida.push({ json: { ...base, tamano: buf.length, valido: false, estado: 'rechazado', error: 'Tipo de archivo no admitido. Solo se aceptan PDF, JPG, PNG, WEBP y HEIC.' }, pairedItem: { item: 0 } });
    continue;
  }
  const hash = crypto.createHash('sha256').update(buf).digest('hex');
  salida.push({
    json: { ...base, tamano: buf.length, mime: tipo.mime, ext: tipo.ext, hash, valido: true },
    binary: { data: { ...meta, mimeType: tipo.mime } },
    pairedItem: { item: 0 },
  });
}
return salida;

const resultados = $input.all()
  .map((i) => i.json)
  .sort((a, b) => (a.orden ?? 0) - (b.orden ?? 0))
  .map(({ orden, ...r }) => r);
const sinArchivos = resultados.length === 1 && resultados[0].archivo === null;
return [{ json: { resultados, _codigo: sinArchivos ? 400 : 200 } }];

const existente = $input.first().json;
const a = $('Recorrer archivos').first(1).json;
return [{ json: { orden: a.orden, archivo: a.archivo, estado: 'duplicada', error: `Archivo idéntico ya registrado (factura id ${existente.id}).`, factura: existente } }];

// Tras la consulta a la Data Table se pierde el item original: lo recuperamos
// (json + referencia al binario) del lote actual del bucle.
const a = $('Recorrer archivos').first(1);
return [{ json: a.json, binary: a.binary }];

// Decide el modo (texto del PDF o visión sobre el binario) y construye la
// petición a Gemini con responseSchema. El LLM solo extrae: no se le pide sumar.
// Modelos (único sitio donde se configuran en la Ingesta; el Asesor tiene los suyos).
// gemini-3.5-flash daba 429 siempre con esta clave (auditoría B8): principal = lite.
const MODELO = 'gemini-3.5-flash-lite';
const MODELO_RESPALDO = 'gemini-3.5-flash';

const archivo = $('Recorrer archivos').first(1).json;
const entrada = $input.first();

let texto = '';
if (archivo.mime === 'application/pdf' && entrada.json && typeof entrada.json.text === 'string') {
  texto = entrada.json.text.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}
const caracteresUtiles = (texto.match(/[A-Za-z0-9ÁÉÍÓÚÜÑáéíóúüñ]/g) || []).length;
const modo = caracteresUtiles >= 60 ? 'texto' : 'vision';

const categorias = $('Leer categorías').all()
  .map((i) => i.json)
  .filter((c) => c && c.nombre && c.activa !== false)
  .sort((a, b) => (a.orden ?? 999) - (b.orden ?? 999))
  .map((c) => c.nombre);
if (!categorias.includes('Otros')) categorias.push('Otros');

const hoy = $now.setZone('Europe/Madrid').toISODate();

const instrucciones = [
  'Eres un extractor de datos de facturas y tickets (mayoritariamente españoles) RECIBIDAS por una empresa, autónomo o particular. Devuelve únicamente lo que aparece en el documento.',
  'Reglas:',
  '- Importes: cópialos EXACTAMENTE como aparecen impresos, como número decimal con punto (12,50 € -> 12.5). NO calcules, NO sumes, NO redondees y NO corrijas importes aunque parezcan incoherentes entre sí. Si un importe no aparece impreso, devuelve null. En facturas rectificativas o de abono, conserva el signo negativo impreso.',
  '- desglose_iva: una línea POR CADA TIPO de IVA impreso (21, 10, 4, 5...), con su base imponible, tipo_iva, cuota_iva y, si hay recargo de equivalencia, tipo_re (5.2, 1.4, 0.5...) y cuota_re. Si no hay recargo, tipo_re y cuota_re = null.',
  '- Ticket con «IVA incluido» sin base ni cuota impresas: pon una línea con tipo_iva = el tipo indicado, base = null, cuota_iva = null e importe_con_iva = importe con IVA de ese tipo si consta. NO calcules la base ni la cuota. Si no consta ningún tipo de IVA, desglose_iva = [].',
  '- base_exenta = suma de bases SIN IVA impresas: exentas, no sujetas, con inversión del sujeto pasivo, intracomunitarias o de fuera de la UE sin IVA. Si no hay, null. No incluyas esas bases en desglose_iva.',
  '- irpf_tipo = porcentaje de retención de IRPF impreso (15, 7, 19...) e irpf_cuota = importe retenido impreso en POSITIVO (en abonos, con el signo impreso). Si no hay retención, null.',
  '- suplidos = gastos pagados por cuenta del cliente (tasas, registros, provisiones de fondos) que se suman sin IVA. Si no hay, null.',
  '- total = TOTAL DE LA FACTURA ANTES DE RESTAR LA RETENCIÓN (bases + IVA + recargo + suplidos). total_a_pagar = importe líquido a pagar DESPUÉS de restar la retención («Total a pagar», «Líquido»). Son dos campos distintos: si hay retención, total es MAYOR que total_a_pagar; si no hay retención, ambos coinciden.',
  '- tipo_factura: "rectificativa" si es rectificativa o abono (e indica rectifica_numero = nº de la factura rectificada, si consta); "simplificada" para tickets y facturas simplificadas; "simplificada_cualificada" si es simplificada y además consta el NIF y el domicilio del destinatario; si no, "completa".',
  '- Fechas en formato AAAA-MM-DD. fecha_emision = fecha de expedición de la factura o ticket. fecha_operacion = fecha de realización de la operación SOLO si se indica expresamente y es distinta; si no, null. fecha_vencimiento solo si aparece expresamente (vencimiento, fecha de cargo o límite de pago); si no, null.',
  '- proveedor = razón social del EMISOR (no del cliente). nif = NIF/CIF/VAT del emisor tal cual (sin espacios). destinatario_nombre y destinatario_nif = nombre y NIF del CLIENTE o destinatario si constan; si no, null.',
  '- mencion_operacion: "inversion_sujeto_pasivo" si menciona inversión del sujeto pasivo (art. 84 LIVA); "reverse_charge" si menciona reverse charge / autoliquidación por el destinatario; "intracomunitaria" si menciona operación intracomunitaria exenta (art. 25 LIVA o similar); "exenta" o "no_sujeta" si menciona exención o no sujeción; si no hay ninguna mención, "ninguna". tipo_iva_autorrepercusion solo si el documento indica qué tipo debe autorrepercutirse; si no, null.',
  '- numero = número de factura/ticket tal como aparece (con su serie). Si no aparece, null.',
  '- moneda = código ISO 4217 (EUR si el símbolo es €, USD si es $ o US$). metodo_pago = tarjeta, efectivo, domiciliación, transferencia, PayPal, Bizum... o null si no consta. pagada = true solo si el documento indica que ya está pagada o cobrada (ticket pagado, «pagado», cargo realizado); si no consta, null.',
  '- lineas = una línea por artículo o concepto comprado, con descripcion tal cual impresa, cantidad (si consta; si no, 1) e importe de esa línea impreso (máximo 40 líneas; si hay más, las 40 de mayor importe). No incluyas líneas de subtotal, total, IVA, entrega, cambio, descuento global ni forma de pago.',
  '- TICKETS DE COMPRA: tipo_factura = "simplificada"; numero = número de ticket, operación o factura simplificada SOLO si consta impreso (si no, null; nunca lo inventes); nif = NIF del establecimiento SOLO si consta (si no, null). Si el ticket tiene tabla de IVA (Base / % IVA / Cuota), una línea de desglose_iva por cada tipo (21, 10, 4) con base y cuota impresas; si solo dice «IVA incluido» con un tipo, aplica la regla de IVA incluido.',
  '- hora = hora de emisión del ticket en formato HH:MM (24 h) si consta; si no, null.',
  '- propina_redondeo = propina, donativo, redondeo u otro importe que figure sumado en el total pero NO esté dentro de ninguna base de IVA; si no hay, null. No lo incluyas en desglose_iva.',
  '- legibilidad: "buena" si lees el documento con seguridad; "dudosa" si hay zonas borrosas, cortadas o torcidas pero el total y los importes principales se leen; "mala" si el total o los importes principales NO se pueden leer con seguridad. Si el total no se lee con seguridad, total = null: no lo adivines.',
  '- Categoría de tickets según el establecimiento y lo comprado: supermercado o tienda de alimentación -> «Alimentación y supermercado»; farmacia o parafarmacia -> «Salud y farmacia»; gasolinera -> «Transporte y combustible»; bar, cafetería o restaurante -> «Restaurantes y comida a domicilio»; ropa o calzado -> «Ropa y calzado»; ferretería, muebles o decoración -> «Hogar»; electrónica -> «Tecnología y electrónica»; suministros del hogar o del local: compañía eléctrica -> «Luz»; agua, Canal de Isabel II, Aigües, EMASESA -> «Agua»; gas natural, butano, Naturgy gas -> «Gas»; telefonía, móvil o fibra (Movistar, Vodafone, Orange, MásMóvil, Digi, Telefónica) -> «Telefonía e internet»; si una factura mezcla luz y gas elige la de mayor importe. Elige siempre una de la lista permitida.',
  '- categoria = exactamente una de la lista permitida. subcategoria = texto corto (p. ej. "Electricidad", "Honorarios de abogado", "Material de obra").',
  '- tipo_suministro: SOLO para facturas de suministros del hogar. Decide por el CONTENIDO de la factura, no por la marca: Endesa, Iberdrola, Naturgy, Repsol, Energía XXI y otras comercializadoras venden luz Y gas. "luz" si facturan electricidad (potencia contratada, kWh de energía eléctrica, peajes, impuesto de electricidad); "gas" si facturan gas natural o GLP (cabecera «Factura de gas», término fijo/variable de gas, m³, poder calorífico, alquiler de equipos de gas); "agua" si es abastecimiento (consumo en m³ de agua, alcantarillado, depuración, saneamiento, tasa de basuras); "telefonia" si es línea móvil, fibra o internet; "otro" para otro suministro; "ninguno" si no es un suministro. La categoría debe ser coherente con este tipo.',
  '- tipo_gasto: "suscripcion" = servicio de pago recurrente que el usuario puede cancelar libremente (streaming, música, apps, software, gimnasio, cuotas de socio); "contrato" = servicio recurrente sujeto a contrato de suministro, alquiler o póliza (luz, agua, gas, internet, telefonía, seguros, alquiler); "puntual" = compra o pago único.',
  '- periodicidad: solo para suscripcion o contrato (semanal, mensual, bimestral, trimestral, semestral, anual), deducida del periodo facturado o de la propia factura; para puntual, null.',
  '- confianza: número entre 0 y 1 con tu seguridad global en la lectura (bájala si la imagen es borrosa, faltan datos clave o dudas de algún importe).',
  '- motivo: una frase breve que justifique la categoría y el tipo de gasto. No repitas importes ni datos personales.',
  `Fecha de hoy (solo para interpretar fechas ambiguas): ${hoy}.`,
].join('\n');

const nullable = (type, extra = {}) => ({ type, nullable: true, ...extra });
const CAMPOS = ['proveedor', 'nif', 'numero', 'tipo_factura', 'rectifica_numero', 'fecha_emision', 'fecha_operacion', 'fecha_vencimiento', 'destinatario_nombre', 'destinatario_nif', 'lineas', 'desglose_iva', 'base_exenta', 'irpf_tipo', 'irpf_cuota', 'suplidos', 'total', 'total_a_pagar', 'mencion_operacion', 'tipo_iva_autorrepercusion', 'moneda', 'metodo_pago', 'pagada', 'hora', 'propina_redondeo', 'legibilidad', 'tipo_suministro', 'categoria', 'subcategoria', 'tipo_gasto', 'periodicidad', 'confianza', 'motivo'];
const responseSchema = {
  type: 'OBJECT',
  properties: {
    proveedor: nullable('STRING'),
    nif: nullable('STRING'),
    numero: nullable('STRING'),
    tipo_factura: { type: 'STRING', enum: ['completa', 'simplificada', 'simplificada_cualificada', 'rectificativa'] },
    rectifica_numero: nullable('STRING'),
    fecha_emision: nullable('STRING', { description: 'AAAA-MM-DD' }),
    fecha_operacion: nullable('STRING', { description: 'AAAA-MM-DD, solo si es distinta de la de emisión' }),
    fecha_vencimiento: nullable('STRING', { description: 'AAAA-MM-DD' }),
    destinatario_nombre: nullable('STRING'),
    destinatario_nif: nullable('STRING'),
    lineas: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          descripcion: { type: 'STRING' },
          cantidad: nullable('NUMBER'),
          precio_unitario: nullable('NUMBER'),
          importe: nullable('NUMBER'),
        },
        required: ['descripcion'],
      },
    },
    desglose_iva: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          base: nullable('NUMBER'),
          tipo_iva: { type: 'NUMBER' },
          cuota_iva: nullable('NUMBER'),
          tipo_re: nullable('NUMBER'),
          cuota_re: nullable('NUMBER'),
          importe_con_iva: nullable('NUMBER', { description: 'solo tickets con IVA incluido sin base ni cuota' }),
        },
        required: ['base', 'tipo_iva', 'cuota_iva', 'tipo_re', 'cuota_re', 'importe_con_iva'],
        propertyOrdering: ['base', 'tipo_iva', 'cuota_iva', 'tipo_re', 'cuota_re', 'importe_con_iva'],
      },
    },
    base_exenta: nullable('NUMBER'),
    irpf_tipo: nullable('NUMBER'),
    irpf_cuota: nullable('NUMBER'),
    suplidos: nullable('NUMBER'),
    total: nullable('NUMBER', { description: 'total de la factura ANTES de restar la retención' }),
    total_a_pagar: nullable('NUMBER', { description: 'líquido a pagar DESPUÉS de restar la retención' }),
    mencion_operacion: { type: 'STRING', enum: ['ninguna', 'inversion_sujeto_pasivo', 'reverse_charge', 'intracomunitaria', 'exenta', 'no_sujeta'] },
    tipo_iva_autorrepercusion: nullable('NUMBER'),
    moneda: nullable('STRING'),
    metodo_pago: nullable('STRING'),
    pagada: nullable('BOOLEAN'),
    hora: nullable('STRING', { description: 'HH:MM del ticket' }),
    propina_redondeo: nullable('NUMBER'),
    legibilidad: { type: 'STRING', enum: ['buena', 'dudosa', 'mala'] },
    tipo_suministro: { type: 'STRING', enum: ['luz', 'gas', 'agua', 'telefonia', 'otro', 'ninguno'] },
    categoria: { type: 'STRING', enum: categorias },
    subcategoria: nullable('STRING'),
    tipo_gasto: { type: 'STRING', enum: ['puntual', 'suscripcion', 'contrato'] },
    periodicidad: nullable('STRING', { enum: ['semanal', 'mensual', 'bimestral', 'trimestral', 'semestral', 'anual'] }),
    confianza: { type: 'NUMBER' },
    motivo: { type: 'STRING' },
  },
  required: CAMPOS,
  propertyOrdering: CAMPOS,
};

const parts = [{ text: instrucciones }];
if (modo === 'texto') {
  parts.push({ text: 'TEXTO DE LA FACTURA (extraído del PDF):\n"""\n' + texto.slice(0, 30000) + '\n"""' });
} else {
  if (!entrada.binary || !entrada.binary.data) {
    return [{ json: { modo: 'error', modelo: MODELO, modelo_respaldo: MODELO_RESPALDO, error: 'No se pudo leer el PDF (dañado o protegido).' } }];
  }
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  parts.push({ text: 'Documento adjunto (imagen o PDF escaneado). Lee la factura completa.' });
  parts.push({ inline_data: { mime_type: archivo.mime, data: buf.toString('base64') } });
}

const peticion = {
  contents: [{ role: 'user', parts }],
  // Sin temperature: en Gemini 3 Google recomienda el valor por defecto.
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema,
    thinkingConfig: { thinkingLevel: 'low' },
  },
};

// texto_factura: lo usa el detector de tipo de suministro de «Interpretar y validar» (no se guarda ni se registra)
return [{ json: { modo, categorias, modelo: MODELO, modelo_respaldo: MODELO_RESPALDO, peticion, texto_factura: modo === 'texto' ? texto.slice(0, 30000) : '' } }];

// Archivos rechazados (tipo/tamaño) o con error de extracción: no se guardan.
const j = $input.first().json;
return [{ json: { orden: j.orden, archivo: j.archivo, estado: j.estado || 'rechazado', error: j.error || 'Error desconocido.' } }];

// Normaliza la extracción de Gemini, asigna el cliente, aplica reglas (cliente >
// global), completa los campos fiscales y valida con cálculos propios (céntimos).
// Si la moneda no es EUR, la entrada es la respuesta del BCE (CSV). Nunca
// incluye contenido de la factura en los mensajes de error.
const archivo = $('Recorrer archivos').first(1).json;
const prep = $('Preparar petición Gemini').first().json;
const g = $('Leer respuesta Gemini').first().json;
if (g._error) return [{ json: { _error: true, orden: archivo.orden, archivo: archivo.archivo, estado: 'error', error: g.error } }];
const d = g.d;

// === COMÚN Ingesta/API: inicio ===
// Bloque idéntico en FACT — Ingesta («Interpretar y validar») y FACT — API
// («PATCH: revalidar y fusionar»). Si cambias algo aquí, cámbialo en ambos.
// Todas las cifras en céntimos enteros. Diseño: docs/diseno-gestoria.md §2.
const num = (x) => {
  if (x === null || x === undefined || x === '') return null;
  let v = x;
  if (typeof v === 'string') {
    v = v.replace(/[^0-9,.\-]/g, '');
    if (v.includes(',') && v.includes('.')) v = v.lastIndexOf(',') > v.lastIndexOf('.') ? v.replace(/\./g, '').replace(',', '.') : v.replace(/,/g, '');
    else v = v.replace(',', '.');
    v = Number(v);
  }
  return typeof v === 'number' && Number.isFinite(v) ? Math.round(v * 100) / 100 : null;
};
const cent = (x) => Math.round(x * 100);
const fechaValida = (s) => {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y, m, dd] = s.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, dd));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === dd && y >= 1990;
};
const txtOrNull = (s) => (typeof s === 'string' && s.trim() ? s.trim() : null);
// Método de pago: primera letra en mayúscula y el resto como venga («tarjeta» → «Tarjeta», «PayPal» igual).
const normalizarMetodoPago = (s) => { const t = txtOrNull(s); return t ? t.charAt(0).toLocaleUpperCase('es-ES') + t.slice(1) : null; };
const SUFIJOS = new Set(['sa', 'sau', 'sl', 'slu', 'sll', 'slne', 'scoop', 'sc', 'cb', 'bv', 'nv', 'ab', 'ltd', 'limited', 'inc', 'llc', 'gmbh', 'ag', 'plc', 'corp', 'corporation', 'spa', 'srl', 'sas', 'sarl', 'oy', 'aps', 'as', 'unipersonal', 'co']);
const normalizarProveedor = (s) => {
  if (!s) return null;
  let t = s.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/\./g, '').replace(/[^a-z0-9]+/g, ' ').trim();
  const w = t.split(' ').filter(Boolean);
  while (w.length > 1 && SUFIJOS.has(w[w.length - 1])) w.pop();
  return w.join(' ') || null;
};
const r2 = (c) => Math.round(c) / 100; // céntimos -> euros

// --- NIF: normalizado (mayúsculas, sin espacios/guiones/puntos, sin «ES» delante de un NIF español) ---
const PAISES_UE = new Set(['AT', 'BE', 'BG', 'CY', 'CZ', 'DE', 'DK', 'EE', 'EL', 'GR', 'FI', 'FR', 'HR', 'HU', 'IE', 'IT', 'LT', 'LU', 'LV', 'MT', 'NL', 'PL', 'PT', 'RO', 'SE', 'SI', 'SK', 'XI']);
const LETRAS_DNI = 'TRWAGMYFPDXBNJZSQVHLCKE';
const normalizarNif = (s) => {
  if (s === null || s === undefined) return null;
  let v = String(s).toUpperCase().replace(/[\s.\-\/]/g, '');
  if (/^ES[0-9A-Z]\d{7}[0-9A-Z]$/.test(v)) v = v.slice(2);
  return v || null;
};
// 'ES' (forma de NIF español), 'UE' (prefijo de país UE distinto de ES), 'EXT' (resto: EIN, EU-OSS, otros países) o null.
const origenNif = (s) => {
  const v = normalizarNif(s);
  if (!v) return null;
  if (/^(\d|[A-Z]\d)/.test(v)) return 'ES';
  if (PAISES_UE.has(v.slice(0, 2))) return 'UE';
  return 'EXT';
};
// true/false según el dígito de control (DNI, NIE, CIF y NIF K/L/M); null si no hay NIF o es extranjero.
const validarNif = (s) => {
  const v = normalizarNif(s);
  if (!v) return null;
  if (origenNif(v) !== 'ES') return null;
  if (/^\d{8}[A-Z]$/.test(v)) return LETRAS_DNI[Number(v.slice(0, 8)) % 23] === v[8];
  if (/^[XYZ]\d{7}[A-Z]$/.test(v)) return LETRAS_DNI[Number('XYZ'.indexOf(v[0]) + v.slice(1, 8)) % 23] === v[8];
  if (/^[ABCDEFGHJKLMNPQRSUVW]\d{7}[0-9A-J]$/.test(v)) {
    let suma = 0;
    v.slice(1, 8).split('').map(Number).forEach((x, i) => {
      if (i % 2 === 0) { const y = x * 2; suma += Math.floor(y / 10) + (y % 10); } else suma += x;
    });
    const ctrl = (10 - (suma % 10)) % 10;
    const letra = 'JABCDEFGHI'[ctrl];
    if ('KLMNPQRSW'.includes(v[0])) return v[8] === letra;
    if ('ABEH'.includes(v[0])) return v[8] === String(ctrl);
    return v[8] === String(ctrl) || v[8] === letra;
  }
  return false;
};

// --- Desglose de IVA: [{base, tipo_iva, cuota_iva, tipo_re, cuota_re}], una línea por tipo ---
// Las líneas al 0 % sin cuota pasan a base_exenta.
const normalizarDesglose = (arr, baseExenta) => {
  let exentaC = cent(num(baseExenta) || 0);
  const lineas = [];
  for (const l of Array.isArray(arr) ? arr : []) {
    if (!l || typeof l !== 'object') continue;
    const x = { base: num(l.base), tipo_iva: num(l.tipo_iva), cuota_iva: num(l.cuota_iva), tipo_re: num(l.tipo_re) || 0, cuota_re: num(l.cuota_re) || 0 };
    if (x.base === null && x.cuota_iva === null) continue;
    if ((x.tipo_iva === 0 || x.tipo_iva === null) && !x.cuota_iva && !x.cuota_re && x.base !== null) { exentaC += cent(x.base); continue; }
    lineas.push(x);
  }
  return { desglose: lineas, base_exenta: r2(exentaC) };
};
// Campos de compatibilidad: base = Σ bases + exenta; iva_tipo = tipo de la base mayor; iva_cuota = Σ cuotas (sin recargo).
const derivarCompat = (desglose, baseExenta) => {
  const exC = cent(baseExenta || 0);
  if (!desglose.length && !exC) return { base: null, iva_tipo: null, iva_cuota: null, cuota_re: 0 };
  if (desglose.some((l) => l.base === null || l.cuota_iva === null)) {
    return { base: desglose.some((l) => l.base === null) ? null : r2(desglose.reduce((s, l) => s + cent(l.base), exC)), iva_tipo: desglose.length ? desglose[0].tipo_iva : 0, iva_cuota: null, cuota_re: r2(desglose.reduce((s, l) => s + cent(l.cuota_re || 0), 0)) };
  }
  let mayor = null;
  for (const l of desglose) if (!mayor || Math.abs(l.base) > Math.abs(mayor.base)) mayor = l;
  return {
    base: r2(desglose.reduce((s, l) => s + cent(l.base), exC)),
    iva_tipo: mayor ? mayor.tipo_iva : 0,
    iva_cuota: r2(desglose.reduce((s, l) => s + cent(l.cuota_iva), 0)),
    cuota_re: r2(desglose.reduce((s, l) => s + cent(l.cuota_re || 0), 0)),
  };
};

// --- Operación y autorrepercusión ---
const OPERACIONES = ['interior', 'intracomunitaria', 'isp_nacional', 'extracomunitaria', 'importacion', 'exenta'];
const AUTORREPERCUTEN = ['intracomunitaria', 'isp_nacional', 'extracomunitaria'];
// mencion: 'inversion_sujeto_pasivo' | 'reverse_charge' | 'intracomunitaria' | 'exenta' | 'no_sujeta' | 'ninguna' | null
const determinarOperacion = ({ nif, desglose, base_exenta, mencion }) => {
  const sinIva = !desglose.some((l) => cent(l.cuota_iva || 0) !== 0);
  const origen = origenNif(nif);
  if (sinIva && (mencion === 'inversion_sujeto_pasivo' || (mencion === 'reverse_charge' && origen === 'ES'))) return 'isp_nacional';
  if (sinIva && origen === 'UE') return 'intracomunitaria';
  if (sinIva && origen === 'EXT') return 'extracomunitaria';
  if (sinIva && cent(base_exenta || 0) !== 0) return 'exenta';
  return 'interior';
};
const calcularAutorrepercutida = (operacion, baseExenta, tipo) => (AUTORREPERCUTEN.includes(operacion)
  ? r2(Math.round((cent(baseExenta || 0) * (typeof tipo === 'number' && tipo > 0 ? tipo : 21)) / 100))
  : 0);

// --- Deducibilidad (orden del diseño §2). cliente = fila de fact_clientes ---
const DEDUCIBLES = ['si', 'no', 'parcial', 'dudoso', 'na'];
const CATEGORIAS_DUDOSAS = ['Restaurantes y comida a domicilio', 'Viajes'];
const calcularDeducible = (f, cliente, forzado) => {
  const regimen = (cliente && cliente.regimen_iva) || 'particular';
  const prorrata = cliente && typeof cliente.prorrata_pct === 'number' && cliente.prorrata_pct >= 0 && cliente.prorrata_pct <= 100 ? cliente.prorrata_pct : 100;
  const ivaC = f.desglose.reduce((s, l) => s + cent(l.cuota_iva || 0), 0) + cent(f.cuota_autorrepercutida || 0);
  const cuotaCon = (pct) => r2(Math.round((ivaC * pct) / 100));
  const res = (deducible, motivo) => ({
    deducible,
    motivo_deducible: motivo,
    cuota_deducible: deducible === 'si' || deducible === 'parcial' ? cuotaCon(prorrata) : 0,
  });
  if (forzado && DEDUCIBLES.includes(forzado.deducible)) return res(forzado.deducible, forzado.motivo || 'Manual: marcado a mano.');
  if (regimen === 'particular') return res('na', 'El cliente es un particular: no deduce IVA.');
  if (regimen === 'recargo_equivalencia') return res('no', 'Cliente en recargo de equivalencia: no deduce el IVA soportado.');
  if (f.tipo_factura === 'simplificada' && !f.destinatario_nif) return res('no', 'Factura simplificada sin NIF del destinatario.');
  if (f.nif_valido === false) return res('no', 'NIF del proveedor no válido (subsanable: pide una factura corregida).');
  if (!f.numero) return res('no', 'Falta el número de factura (subsanable).');
  if (CATEGORIAS_DUDOSAS.includes(f.categoria)) return res('dudoso', 'Restauración o viajes: deducible solo si está afecto a la actividad.');
  if (ivaC === 0) return res('na', 'Sin IVA soportado ni autorrepercutido.');
  if (prorrata < 100) return res('parcial', `Deducible al ${prorrata} % (prorrata del cliente).`);
  return res('si', AUTORREPERCUTEN.includes(f.operacion) ? 'Deducible: IVA autorrepercutido.' : 'Factura completa con los datos obligatorios.');
};

// --- Reglas y cuentas: regla del cliente > regla global > categoría.cuenta_pgc > 629 ---
const buscarRegla = (reglas, proveedorNorm, clienteId, campo) => {
  if (!proveedorNorm) return null;
  const tiene = (r) => r && r.proveedor_norm === proveedorNorm && txtOrNull(r[campo]);
  return (reglas || []).find((r) => tiene(r) && r.cliente_id === clienteId)
    || (reglas || []).find((r) => tiene(r) && (r.cliente_id === null || r.cliente_id === undefined))
    || null;
};
const resolverCuenta = (proveedorNorm, categoria, clienteId, reglas, categorias) => {
  const regla = buscarRegla(reglas, proveedorNorm, clienteId, 'cuenta_gasto');
  const cat = (categorias || []).find((c) => c && c.nombre === categoria);
  const cuenta = (regla && txtOrNull(regla.cuenta_gasto)) || (cat && txtOrNull(cat.cuenta_pgc)) || '629';
  return { cuenta_gasto: cuenta, cuenta_proveedor: cuentaProveedor(cuenta) };
};
const cuentaProveedor = (cuenta) => (String(cuenta || '').startsWith('60') ? '400' : '410');

// --- Moneda: tipo_cambio = EUR por 1 unidad (BCE); total_eur = total × tipo_cambio ---
const aplicarCambio = (f, tipoCambio) => {
  if (!f.moneda || f.moneda === 'EUR') return { tipo_cambio: 1, total_eur: f.total };
  if (typeof tipoCambio !== 'number' || !(tipoCambio > 0) || f.total === null) return { tipo_cambio: null, total_eur: null };
  return { tipo_cambio: tipoCambio, total_eur: r2(Math.round(cent(f.total) * tipoCambio)) };
};
// CSV del BCE (format=csvdata): último OBS_VALUE con TIME_PERIOD <= fecha. Devuelve EUR por unidad (1/valor) o null.
const tipoCambioBce = (csv, fecha) => {
  if (typeof csv !== 'string' || !csv.trim()) return null;
  const lineas = csv.trim().split(/\r?\n/);
  const cab = lineas[0].split(',');
  const iT = cab.indexOf('TIME_PERIOD');
  const iV = cab.indexOf('OBS_VALUE');
  if (iT < 0 || iV < 0) return null;
  let mejor = null;
  for (const l of lineas.slice(1)) {
    const c = l.split(',');
    const v = Number(c[iV]);
    if (/^\d{4}-\d{2}-\d{2}$/.test(c[iT]) && c[iT] <= fecha && v > 0 && (!mejor || c[iT] > mejor.t)) mejor = { t: c[iT], v };
  }
  return mejor ? Math.round((1 / mejor.v) * 1e6) / 1e6 : null;
};

// --- Nº de recepción: siguiente correlativo del cliente en el año ---
const siguienteRecepcion = (filas, clienteId, anio) => {
  const pre = `${anio}-`;
  let max = 0;
  for (const f of filas || []) {
    if (f && f.cliente_id === clienteId && typeof f.num_recepcion === 'string' && f.num_recepcion.startsWith(pre)) {
      const n = Number(f.num_recepcion.slice(pre.length));
      if (Number.isFinite(n) && n > max) max = n;
    }
  }
  return pre + String(max + 1).padStart(6, '0');
};

// --- Completa los campos fiscales derivados de una factura (Ingesta, PATCH y migración) ---
// f: nif, destinatario_nif, numero, categoria, tipo_factura, desglose (array), base_exenta, suplidos,
//    irpf_tipo, irpf_cuota, total, moneda, tipo_cambio, operacion (indicada o null), mencion, tipo_autorrepercusion.
const TIPOS_FACTURA = ['completa', 'simplificada', 'simplificada_cualificada', 'rectificativa'];
const completarFiscal = (f, cliente, forzado) => {
  const nd = normalizarDesglose(f.desglose, f.base_exenta);
  const total = num(f.total);
  const compat = derivarCompat(nd.desglose, nd.base_exenta);
  const tipo_factura = TIPOS_FACTURA.includes(f.tipo_factura) ? f.tipo_factura : 'completa';
  let irpf_cuota = num(f.irpf_cuota);
  const irpf_tipo = num(f.irpf_tipo) || 0;
  if (irpf_cuota === null && irpf_tipo > 0) {
    const baseIrpfC = nd.desglose.reduce((s, l) => s + cent(l.base || 0), 0);
    irpf_cuota = r2(Math.round((baseIrpfC * irpf_tipo) / 100));
  }
  irpf_cuota = Math.abs(irpf_cuota || 0);
  if (total !== null && total < 0) irpf_cuota = -irpf_cuota; // rectificativas: retención negativa
  const nif = normalizarNif(f.nif);
  const destinatario_nif = normalizarNif(f.destinatario_nif);
  const operacion = OPERACIONES.includes(f.operacion) ? f.operacion
    : determinarOperacion({ nif, desglose: nd.desglose, base_exenta: nd.base_exenta, mencion: f.mencion });
  const cuota_autorrepercutida = calcularAutorrepercutida(operacion, nd.base_exenta, num(f.tipo_autorrepercusion));
  const nif_valido = validarNif(nif);
  const moneda = typeof f.moneda === 'string' && /^[A-Z]{3}$/.test(f.moneda) ? f.moneda : 'EUR';
  const cambio = aplicarCambio({ moneda, total }, num(f.tipo_cambio) === null ? null : Number(f.tipo_cambio));
  const base = {
    nif,
    destinatario_nif,
    tipo_factura,
    operacion,
    desglose: nd.desglose,
    desglose_iva_json: JSON.stringify(nd.desglose),
    base_exenta: nd.base_exenta,
    base: compat.base,
    iva_tipo: compat.iva_tipo,
    iva_cuota: compat.iva_cuota,
    cuota_re: compat.cuota_re,
    irpf_tipo,
    irpf_cuota,
    suplidos: num(f.suplidos) || 0,
    total,
    total_a_pagar: total === null ? null : r2(cent(total) - cent(irpf_cuota)),
    cuota_autorrepercutida,
    nif_valido,
    moneda,
    tipo_cambio: cambio.tipo_cambio,
    total_eur: cambio.total_eur,
  };
  const ded = calcularDeducible({ ...base, numero: txtOrNull(f.numero), categoria: f.categoria }, cliente, forzado);
  return { ...base, ...ded };
};

// --- Validación (céntimos). hoy = AAAA-MM-DD en Europe/Madrid. total_a_pagar_leido: el impreso (Ingesta) ---
const validarFactura = (f, hoy) => {
  const errores = [];
  const fmt = (x) => x.toFixed(2);
  if (!f.proveedor) errores.push('No se ha identificado el proveedor.');
  if (f.total === null) errores.push('No se ha encontrado el total.');
  else if (cent(f.total) === 0) errores.push('El total no puede ser 0.');
  else if (f.total < 0 && f.tipo_factura !== 'rectificativa') errores.push(`El total (${fmt(f.total)}) es negativo y la factura no es rectificativa.`);
  const desglose = f.desglose || [];
  const exC = cent(f.base_exenta || 0);
  if (!desglose.length && !exC) {
    errores.push('No se puede comprobar base + IVA = total: falta base imponible y cuota de IVA.');
  } else if (desglose.some((l) => l.base === null || l.cuota_iva === null)) {
    const faltan = [desglose.some((l) => l.base === null) ? 'base imponible' : null, desglose.some((l) => l.cuota_iva === null) ? 'cuota de IVA' : null].filter(Boolean).join(' y ');
    errores.push(`No se puede comprobar base + IVA = total: falta ${faltan}.`);
  } else if (f.total !== null) {
    const baseC = desglose.reduce((s, l) => s + cent(l.base), 0) + exC;
    const ivaC = desglose.reduce((s, l) => s + cent(l.cuota_iva), 0);
    const reC = desglose.reduce((s, l) => s + cent(l.cuota_re || 0), 0);
    const supC = cent(f.suplidos || 0);
    const sumaC = baseC + ivaC + reC + supC;
    const dif = sumaC - cent(f.total);
    if (Math.abs(dif) > 2) {
      if (!reC && !supC) errores.push(`Base (${fmt(baseC / 100)}) + IVA (${fmt(ivaC / 100)}) = ${fmt(sumaC / 100)}, no cuadra con el total (${fmt(f.total)}): diferencia de ${fmt(dif / 100)} €.`);
      else errores.push(`Base (${fmt(baseC / 100)}) + IVA (${fmt(ivaC / 100)}) + recargo (${fmt(reC / 100)}) + suplidos (${fmt(supC / 100)}) = ${fmt(sumaC / 100)}, no cuadra con el total (${fmt(f.total)}): diferencia de ${fmt(dif / 100)} €.`);
    }
  }
  if (f.total !== null && f.total_a_pagar_leido !== null && f.total_a_pagar_leido !== undefined) {
    const esperado = cent(f.total) - cent(f.irpf_cuota || 0);
    const dif = esperado - cent(f.total_a_pagar_leido);
    if (Math.abs(dif) > 2) errores.push(`Total (${fmt(f.total)}) − retención (${fmt(f.irpf_cuota || 0)}) = ${fmt(esperado / 100)}, no cuadra con el total a pagar (${fmt(f.total_a_pagar_leido)}).`);
  }
  if (!f.fecha_emision) errores.push('Fecha de emisión ausente o no válida.');
  else if (f.fecha_emision > hoy) errores.push(`La fecha de emisión (${f.fecha_emision}) es futura.`);
  if (f.moneda && f.moneda !== 'EUR' && (f.total_eur === null || f.total_eur === undefined)) errores.push(`Sin tipo de cambio para ${f.moneda}: no se suma en los totales en euros.`);
  return errores;
};
// === COMÚN Ingesta/API: fin ===

// --- contexto ---
const hoy = $now.setZone('Europe/Madrid').toISODate();
const ahora = $now.setZone('Europe/Madrid').toISO();
const categorias = prep.categorias || [];
const filasCategorias = $('Leer categorías').all().map((i) => i.json).filter((c) => c && c.nombre);
const reglas = $('Leer reglas').all().map((i) => i.json).filter((x) => x && x.proveedor_norm);
const clientes = $('Leer clientes').all().map((i) => i.json).filter((c) => c && c.id !== undefined && c.id !== null);

// --- normalización ---
const proveedor = txtOrNull(d.proveedor);
const proveedor_norm = normalizarProveedor(proveedor);
const numero = txtOrNull(d.numero);
const total = num(d.total);
const fecha_emision = fechaValida(d.fecha_emision) ? d.fecha_emision : null;
const fecha_vencimiento = fechaValida(d.fecha_vencimiento) ? d.fecha_vencimiento : null;
const fecha_operacion = fechaValida(d.fecha_operacion) ? d.fecha_operacion : fecha_emision;
let confianza = num(d.confianza);
confianza = confianza === null ? 0 : Math.min(1, Math.max(0, confianza));
const tipo_gasto = ['puntual', 'suscripcion', 'contrato'].includes(d.tipo_gasto) ? d.tipo_gasto : 'puntual';
const PERIODOS = ['semanal', 'mensual', 'bimestral', 'trimestral', 'semestral', 'anual'];
const periodicidad = tipo_gasto !== 'puntual' && PERIODOS.includes(d.periodicidad) ? d.periodicidad : null;
const lineas = Array.isArray(d.lineas) ? d.lineas.slice(0, 40).map((l) => ({
  descripcion: txtOrNull(l && l.descripcion) || '',
  cantidad: num(l && l.cantidad),
  precio_unitario: num(l && l.precio_unitario),
