if (!cliente) { cliente = clientes.find((c) => c.nombre === 'Personal') || activos.find((c) => c.regimen_iva === 'particular') || null; asignacion = 'personal'; }
const clienteId = cliente ? cliente.id : null;

// === TIPO SUMINISTRO: inicio ===
// Detector determinista del tipo de suministro por el CONTENIDO (no por la marca: Endesa, Iberdrola,
// Naturgy o Energía XXI venden luz y gas). Puntúa cada tipo con patrones sobre el texto de la factura,
// las descripciones de las líneas, la subcategoría y el nombre del archivo.
const SUM_CAT = { luz: 'Luz', gas: 'Gas', agua: 'Agua', telefonia: 'Telefonía e internet' };
const SUM_PAT = {
  luz: [[/factura de electricidad|factura de luz|suministro (de )?electric/, 8], [/potencia contratada/, 4], [/energia activa/, 3],
    [/impuesto (sobre la )?electricidad|impuesto electricidad/, 4], [/\bpeajes? de (transporte|acceso)|\bpeajes?\b/, 2], [/\b[23]\.0 ?td\b|\b6\.1 ?td\b/, 4],
    [/termino de potencia|termino fijo.{0,20}potencia/, 3], [/punta-llano|\bvalle\b.{0,30}\bkw\b|\bkw\b/, 2], [/discriminacion horaria|contador electrico|alquiler (del )?contador/, 2], [/\belectricidad\b|\belectrica\b|\bluz\b/, 1]],
  gas: [[/factura de gas\b/, 8], [/datos del contrato de gas|informacion del consumo gas/, 5], [/termino (fijo|energia|variable) gas|alquiler de equipos gas/, 5],
    [/gas natural/, 4], [/tipo de gas/, 3], [/kwh ?\/ ?m3/, 4], [/poder calorifico|\bpcs\b|coeficiente de conversion/, 3], [/\b(butano|propano|glp)\b/, 4], [/enagas|red de gas/, 2], [/\bgas\b/, 1]],
  agua: [[/factura de agua|consumo de agua|m3 de agua|suministro de agua/, 6], [/canal de isabel|aigues|emasesa|aguas de /, 5], [/alcantarillado/, 4], [/depuracion/, 3], [/saneamiento/, 3],
    [/abastecimiento/, 3], [/tasa de basuras|cuota de servicio/, 2], [/\bagua\b/, 1]],
  telefonia: [[/\bfibra\b/, 4], [/movistar|vodafone|orange|masmovil|\bdigi\b|yoigo|pepephone|jazztel|\bo2\b|simyo|lowi/, 3], [/\blineas? (movil|fija|5g|4g)|lineas? 5g|\b5g\+?/, 3],
    [/datos moviles|\bgb\b|roaming|\bsms\b/, 2], [/\binternet\b/, 2], [/llamadas/, 2], [/telefono|telefonia|\bmovil(es)?\b/, 1], [/\bfusion\b/, 2]],
};
const sumNorm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/m³/g, 'm3').replace(/[  \t]+/g, ' ');
// textos: { texto, lineas: [descripciones], subcategoria, archivo }. El archivo suma 3 puntos por tipo (pista débil).
const detectarSuministro = (textos) => {
  const cuerpo = sumNorm([textos.texto, ...(textos.lineas || []), textos.subcategoria].filter(Boolean).join('\n'));
  const nombre = sumNorm(textos.archivo);
  const puntos = { luz: 0, gas: 0, agua: 0, telefonia: 0 };
  for (const t of Object.keys(SUM_PAT)) for (const [re, w] of SUM_PAT[t]) if (re.test(cuerpo)) puntos[t] += w;
  if (/(^|[^a-z])(luz|electricidad)([^a-z]|$)/.test(nombre)) puntos.luz += 3;
  if (/(^|[^a-z])gas([^a-z]|$)/.test(nombre)) puntos.gas += 3;
  if (/(^|[^a-z])agua([^a-z]|$)/.test(nombre)) puntos.agua += 3;
  if (/telefon|movistar|internet|fibra/.test(nombre)) puntos.telefonia += 3;
  const orden = Object.keys(puntos).sort((a, b) => puntos[b] - puntos[a]);
  const mejor = puntos[orden[0]], segundo = puntos[orden[1]];
  return {
    tipo: mejor > 0 ? orden[0] : null, puntos,
    concluyente: mejor >= 6 && mejor >= 2 * segundo, // fija el tipo, por encima de Gemini
    evidencia: mejor >= 4 && mejor > segundo, // basta para avisar de una incoherencia
  };
};
// Tipo final: detector concluyente > tipo_suministro de Gemini (luz/gas/agua/telefonia) > ninguno.
const decidirSuministro = (det, tipoGemini) => {
  if (det.concluyente) return { tipo: det.tipo, origen: 'contenido' };
  if (SUM_CAT[tipoGemini]) return { tipo: tipoGemini, origen: 'gemini' };
  return { tipo: null, origen: null };
};
// === TIPO SUMINISTRO: fin ===

// --- categoría: el tipo de suministro se decide por el CONTENIDO; una regla de proveedor nunca impone Luz/Gas/Agua/Telefonía sobre otro tipo ---
let categoria = categorias.includes(d.categoria) ? d.categoria : 'Otros';
let subcategoria = txtOrNull(d.subcategoria);
let origen_categoria = 'llm';
const det = detectarSuministro({ texto: prep.texto_factura, lineas: lineas.map((l) => l.descripcion), subcategoria, archivo: archivo.archivo });
const sumin = decidirSuministro(det, d.tipo_suministro);
const catSum = Object.values(SUM_CAT);
if (sumin.tipo && categorias.includes(SUM_CAT[sumin.tipo])) categoria = SUM_CAT[sumin.tipo];
const reglaCat = buscarRegla(reglas, proveedor_norm, clienteId, 'categoria');
// Las reglas de proveedor con categoría de suministro se ignoran siempre: el tipo sale del contenido (o de Gemini), nunca de la marca.
if (reglaCat && !catSum.includes(reglaCat.categoria)) {
  categoria = reglaCat.categoria;
  if (txtOrNull(reglaCat.subcategoria)) subcategoria = reglaCat.subcategoria;
  origen_categoria = 'regla';
}
const incoherencia = catSum.includes(categoria) && det.evidencia && SUM_CAT[det.tipo] !== categoria ? SUM_CAT[det.tipo] : null;

// --- desglose: ticket con IVA incluido sin base ni cuota => base y cuota calculadas aquí a partir del tipo leído ---
// Propina / redondeo (ticket): importe sumado al total que no está en ninguna base de IVA; se trata como suplido para que Σ cuadre.
const propina = Math.max(0, num(d.propina_redondeo) || 0);
const suplidosLeidos = r2(cent(num(d.suplidos) || 0) + cent(propina));
const exentaLeida = num(d.base_exenta) || 0;
const crudo = Array.isArray(d.desglose_iva) ? d.desglose_iva : [];
const calculadas = [];
const desgloseLeido = crudo.map((l) => {
  const x = { base: num(l && l.base), tipo_iva: num(l && l.tipo_iva), cuota_iva: num(l && l.cuota_iva), tipo_re: num(l && l.tipo_re), cuota_re: num(l && l.cuota_re) };
  if (x.base === null && x.cuota_iva === null && x.tipo_iva !== null && x.tipo_iva > 0) {
    let conIva = num(l && l.importe_con_iva);
    if (conIva === null && crudo.length === 1 && total !== null) conIva = r2(cent(total) - cent(exentaLeida) - cent(suplidosLeidos));
    if (conIva !== null) {
      const tre = x.tipo_re || 0;
      const baseC = Math.round((cent(conIva) * 100) / (100 + x.tipo_iva + tre));
      const reC = tre ? Math.round((baseC * tre) / 100) : 0;
      x.base = r2(baseC);
      x.cuota_iva = r2(cent(conIva) - baseC - reC);
      if (tre) x.cuota_re = r2(reC);
      calculadas.push(x.tipo_iva);
    }
  }
  return x;
});

const fx = completarFiscal({
  nif: txtOrNull(d.nif), destinatario_nif, numero, categoria, tipo_factura: d.tipo_factura,
  desglose: desgloseLeido, base_exenta: exentaLeida, suplidos: suplidosLeidos,
  irpf_tipo: d.irpf_tipo, irpf_cuota: d.irpf_cuota, total, moneda: g.moneda, tipo_cambio: null,
  operacion: null, mencion: d.mencion_operacion, tipo_autorrepercusion: d.tipo_iva_autorrepercusion,
}, cliente, null);

// --- tipo de cambio (BCE) si la moneda no es EUR ---
if (fx.moneda !== 'EUR') {
  const resp = $input.first().json || {};
  const tc = tipoCambioBce(typeof resp.data === 'string' ? resp.data : null, g.bce.fecha);
  const c = aplicarCambio({ moneda: fx.moneda, total: fx.total }, tc);
  fx.tipo_cambio = c.tipo_cambio;
  fx.total_eur = c.total_eur;
}
const cuentas = resolverCuenta(proveedor_norm, categoria, clienteId, reglas, filasCategorias);

// --- validación (bloque común) + umbral de confianza (solo Ingesta) ---
const errores = validarFactura({
  proveedor, total: fx.total, desglose: fx.desglose, base_exenta: fx.base_exenta, suplidos: fx.suplidos,
  irpf_cuota: fx.irpf_cuota, total_a_pagar_leido: num(d.total_a_pagar), tipo_factura: fx.tipo_factura,
  fecha_emision, moneda: fx.moneda, total_eur: fx.total_eur,
}, hoy);
if (incoherencia) errores.push(`La categoría (${categoria}) no coincide con el contenido de la factura (parece ${incoherencia}).`);
if (confianza < 0.75) errores.push(`Confianza de extracción baja (${confianza.toFixed(2)} < 0,75).`);
// Tickets: foto borrosa/torcida con importes ilegibles => revisar con motivo claro
const legibilidad = ['buena', 'dudosa', 'mala'].includes(d.legibilidad) ? d.legibilidad : 'buena';
if (legibilidad === 'mala') errores.push('Imagen borrosa, torcida o cortada: los importes no se leen con seguridad. Revisa el ticket y corrige los datos.');
const hora = typeof d.hora === 'string' && /^([01]?\d|2[0-3]):[0-5]\d$/.test(d.hora.trim()) ? d.hora.trim().padStart(5, '0') : null;
let motivoTxt = txtOrNull(d.motivo);
if (propina > 0) motivoTxt = ((motivoTxt || '') + ` Incluye propina/redondeo de ${propina.toFixed(2).replace('.', ',')} €.`).trim();
if (legibilidad === 'dudosa') motivoTxt = ((motivoTxt || '') + ' Imagen de calidad dudosa: conviene comprobar los importes.').trim();

// --- pago: pagada si el documento lo dice o si el método implica cargo inmediato ---
const metodo_pago = normalizarMetodoPago(d.metodo_pago);
const CARGO = ['tarjeta', 'paypal', 'efectivo', 'bizum', 'domiciliación', 'domiciliacion'];
const vencida = fecha_vencimiento && fecha_vencimiento > hoy;
const pagada = d.pagada === true || (CARGO.includes(String(metodo_pago || '').toLowerCase()) && !vencida);

// --- ruta del original: AAAA/MM de la fecha de emisión (o de hoy si no es válida) ---
const fRuta = fecha_emision && fecha_emision <= hoy ? fecha_emision : hoy;
const archivo_ruta = `/home/node/.n8n-files/facturas/${fRuta.slice(0, 4)}/${fRuta.slice(5, 7)}/${archivo.hash}.${archivo.ext}`;

const fila = {
  usuario_id: 'default',
  hash_sha256: archivo.hash,
  archivo_ruta,
  archivo_nombre: archivo.archivo,
  mime: archivo.mime,
  proveedor,
  proveedor_norm,
  nif: fx.nif,
  numero,
  fecha_emision,
  fecha_vencimiento,
  lineas_json: JSON.stringify(lineas),
  base: fx.base,
  iva_tipo: fx.iva_tipo,
  iva_cuota: fx.iva_cuota,
  total: fx.total,
  moneda: fx.moneda,
  metodo_pago,
  categoria,
  subcategoria,
  tipo_gasto,
  periodicidad,
  confianza: Math.round(confianza * 100) / 100,
  motivo: motivoTxt,
  estado: errores.length ? 'revisar' : 'ok',
  errores_validacion: null,
  origen_categoria,
  creado: ahora,
  actualizado: ahora,
  cliente_id: clienteId,
  destinatario_nif: fx.destinatario_nif,
  tipo_factura: fx.tipo_factura,
  rectifica_numero: txtOrNull(d.rectifica_numero),
  fecha_operacion,
  operacion: fx.operacion,
  desglose_iva_json: fx.desglose_iva_json,
  base_exenta: fx.base_exenta,
  cuota_re: fx.cuota_re,
  irpf_tipo: fx.irpf_tipo,
  irpf_cuota: fx.irpf_cuota,
  suplidos: fx.suplidos,
  total_a_pagar: fx.total_a_pagar,
  cuota_autorrepercutida: fx.cuota_autorrepercutida,
  nif_valido: fx.nif_valido,
  deducible: fx.deducible,
  motivo_deducible: fx.motivo_deducible,
  cuota_deducible: fx.cuota_deducible,
  cuenta_gasto: cuentas.cuenta_gasto,
  cuenta_proveedor: cuentas.cuenta_proveedor,
  tipo_cambio: fx.tipo_cambio,
  total_eur: fx.total_eur,
  num_recepcion: null,
  estado_pago: pagada ? 'pagada' : 'pendiente',
  fecha_pago: pagada ? fecha_emision : null,
  movimiento_id: null,
  hora,
};

const extraccion = { modo: prep.modo, modelo: g.modelo, cliente: asignacion };
if (calculadas.length) extraccion.base_calculada = calculadas;
return [{ json: { _error: false, orden: archivo.orden, archivo: archivo.archivo, extraccion, errores, fila } }];

// Entrada: todas las facturas del mismo cliente (cualquier estado).
// 1) Duplicado lógico: mismo proveedor_norm + número + total (al céntimo) en una
//    factura no borrada del cliente => posible_duplicada. Si no, revisar/ok.
// 2) Nº de recepción: siguiente correlativo del cliente en el año de emisión
//    (misma regla que siguienteRecepcion del bloque COMÚN; las borradas no liberan su número).
const v = $('Interpretar y validar').first().json;
const fila = { ...v.fila };
const errores = [...(v.errores || [])];
const delCliente = $input.all().map((i) => i.json).filter((x) => x && x.id !== undefined && x.id !== null && x.cliente_id === fila.cliente_id);

let estado = errores.length ? 'revisar' : 'ok';
if (fila.proveedor_norm && fila.numero && fila.total !== null) {
  const dup = delCliente.find((x) => x.estado !== 'borrada' && x.proveedor_norm === fila.proveedor_norm && x.numero === fila.numero && x.total !== null && Math.round(x.total * 100) === Math.round(fila.total * 100));
  if (dup) {
    estado = 'posible_duplicada';
    errores.push(`Posible duplicada de la factura id ${dup.id} (mismo proveedor, número y total).`);
  }
}
// Ticket sin número: duplicado lógico = mismo proveedor + fecha + total (+ hora si ambos la tienen y es distinta => no es duplicado).
if (estado !== 'posible_duplicada' && !fila.numero && fila.proveedor_norm && fila.fecha_emision && fila.total !== null) {
  const dupT = delCliente.find((x) => x.estado !== 'borrada' && !x.numero && x.proveedor_norm === fila.proveedor_norm && x.fecha_emision === fila.fecha_emision && x.total !== null && Math.round(x.total * 100) === Math.round(fila.total * 100) && !(x.hora && fila.hora && x.hora !== fila.hora));
  if (dupT) {
    estado = 'posible_duplicada';
    errores.push(`Posible duplicada del ticket id ${dupT.id} (mismo comercio, fecha${fila.hora ? ', hora' : ''} e importe).`);
  }
}
fila.estado = estado;
fila.errores_validacion = errores.length ? errores.join(' | ') : null;

const hoy = $now.setZone('Europe/Madrid').toISODate();
const anio = (fila.fecha_emision && fila.fecha_emision <= hoy ? fila.fecha_emision : hoy).slice(0, 4);
let max = 0;
for (const x of delCliente) {
  if (typeof x.num_recepcion === 'string' && x.num_recepcion.startsWith(anio + '-')) {
    const n = Number(x.num_recepcion.slice(5));
    if (Number.isFinite(n) && n > max) max = n;
  }
}
fila.num_recepcion = `${anio}-${String(max + 1).padStart(6, '0')}`;

const original = $('Recorrer archivos').first(1);
return [{ json: { orden: v.orden, archivo: v.archivo, extraccion: v.extraccion, fila }, binary: original.binary }];

const f = $input.first().json;
const d = $('Decidir estado final').first().json;
const res = { orden: d.orden, archivo: d.archivo, estado: f.estado, factura: f, extraccion: d.extraccion };
if (f.estado !== 'ok' && f.errores_validacion) res.error = f.errores_validacion;
return [{ json: res }];

// Crea la carpeta AAAA/MM del original antes de escribirlo (el nodo Read/Write
// Files no crea carpetas). AAAA/MM = fecha de emisión; si no es válida o es
// futura, mes de subida (lo decide "Interpretar y validar").
const fs = require('fs');
const path = require('path');
const RAIZ = '/home/node/.n8n-files/facturas/';
return $input.all().map((it) => {
  const ruta = path.posix.normalize(String((it.json.fila && it.json.fila.archivo_ruta) || ''));
  if (!ruta.startsWith(RAIZ) || !/^\d{4}\/\d{2}\/[0-9a-f]{64}\.[a-z0-9]+$/.test(ruta.slice(RAIZ.length))) {
    throw new Error('Ruta del original no válida para el almacén.');
  }
  fs.mkdirSync(path.posix.dirname(ruta), { recursive: true });
  return { json: it.json, binary: it.binary };
});

// Lee la respuesta de Gemini (principal o respaldo) y decide si hace falta el
// tipo de cambio del BCE. Al BCE solo se envían la moneda y la fecha.
const prep = $('Preparar petición Gemini').first().json;
const r = $input.first().json || {};
const fallo = (msg) => [{ json: { _error: true, error: msg, moneda: 'EUR' } }];

if (prep.modo === 'error') return fallo(prep.error || 'No se pudo preparar el archivo para su lectura.');
if (r.error) {
  const msg = typeof r.error === 'string' ? r.error : (r.error.message || '');
  return fallo('No se pudo extraer la factura con Gemini: ' + String(msg).slice(0, 150));
}
const cand = (r.candidates || [])[0];
const txt = cand && cand.content && Array.isArray(cand.content.parts) ? cand.content.parts.map((p) => p.text || '').join('') : '';
if (!txt) {
  const razon = (cand && cand.finishReason) || (r.promptFeedback && r.promptFeedback.blockReason) || 'sin respuesta';
  return fallo('Gemini no devolvió datos (' + razon + ').');
}
let d;
try { d = JSON.parse(txt); } catch (e) { return fallo('La respuesta de Gemini no es un JSON válido.'); }
if (!d || typeof d !== 'object' || Array.isArray(d)) return fallo('La respuesta de Gemini no es un objeto JSON.');

const SIMBOLOS = { '€': 'EUR', EURO: 'EUR', EUROS: 'EUR', $: 'USD', US$: 'USD', USD$: 'USD', '£': 'GBP' };
let moneda = typeof d.moneda === 'string' && d.moneda.trim() ? d.moneda.trim().toUpperCase() : 'EUR';
moneda = SIMBOLOS[moneda] || moneda;
if (!/^[A-Z]{3}$/.test(moneda)) moneda = 'EUR';

const hoy = $now.setZone('Europe/Madrid').toISODate();
const okFecha = typeof d.fecha_emision === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d.fecha_emision) && DateTime.fromISO(d.fecha_emision).isValid && d.fecha_emision <= hoy;
const finBce = okFecha ? d.fecha_emision : hoy; // BCE: día de emisión o el último hábil anterior (ventana de 7 días)
const inicioBce = DateTime.fromISO(finBce).minus({ days: 7 }).toISODate();
return [{ json: { _error: false, d, modelo: r.modelVersion || null, moneda, bce: { fecha: finBce, desde: inicioBce } } }];
